// background" (OSC 111) sequences found in out. Both are searched as whole
// sequences because they share the ESC ] 11 prefix.
func bgSequences(out string) []string {
	var seqs []string
	for _, m := range bgSeqRe.FindAllStringSubmatch(out, -1) {
		if m[1] == "111" {
