// waitOut polls until cond(out) holds, or fails after a guard timeout.
func waitOut(t *testing.T, out *lockedBuffer, what string, cond func(string) bool) {
	t.Helper()
	deadline := time.Now().Add(5 * time.Second)
	for !cond(out.String()) {
		if time.Now().After(deadline) {
			t.Errorf("timed out waiting for %s; output so far: %q", what, out.String())
			return
		}
		time.Sleep(5 * time.Millisecond)
	}
