// waitOut polls until cond(out) holds, or fails after a guard timeout.
func waitOut(t *testing.T, out *lockedBuffer, what string, cond func(string) bool) {
	t.Helper()
	deadline := time.Now().Add(5 * time.Second)
	for !cond(out.String()) {
		if time.Now().After(deadline) {
			t.Errorf("timed out waiting for %s; output so far: %q", what, out.String())
			return
		}
		time.Sleep(5 * time.Millisecond)
	}
}

// runRouter runs a around a real program writing to a buffer, after the first
// frame ("hello") script runs; the program is given profile. It fails the test
// when the program outlives a guard timeout.
func runRouter(t *testing.T, a *App, profile colorprofile.Profile, script func(p *tea.Program, out *lockedBuffer)) (string, error) {
	t.Helper()
	out := &lockedBuffer{}
	p := tea.NewProgram(a, tea.WithInput(nil), tea.WithOutput(out),
		tea.WithWindowSize(100, 30), tea.WithoutSignalHandler(), tea.WithColorProfile(profile))
	go func() {
		waitOut(t, out, "the first frame", func(s string) bool { return strings.Contains(s, "hello") })
		script(p, out)
	}()
	type result struct{ err error }
	done := make(chan result, 1)
	go func() { _, err := p.Run(); done <- result{err} }()
	select {
	case r := <-done:
		return out.String(), r.err
	case <-time.After(10 * time.Second):
		p.Kill()
		t.Fatal("the program did not exit")
		return "", nil
	}
